/**
 * lib/industries.ts
 *
 * The Industries section of the public site. One entry per sector we have
 * actually built for.
 *
 * Registry-driven rather than six hand-authored pages, following the pattern
 * lib/registry/products.ts established: content lives in one reviewable file,
 * the route renders it. Adding a sector is a data change.
 *
 * Every entry follows the same five-part structure, which is the order a
 * business reads in and the order a consultant would speak in:
 *
 *   problem   what goes wrong, in the operator's own terms
 *   reality   why it happens — usually not incompetence, usually structural
 *   approach  what we actually do about it
 *   outcome   what changes afterwards, stated without numbers we cannot source
 *   next      the one action that makes sense next
 *
 * Writing rules applied throughout: business before technology, no product
 * names (the operating systems are protected and are not sold from here), no
 * metrics we cannot evidence, and none of the vocabulary the brief bans —
 * no "AI-powered", "seamless", "leverage", "enterprise-grade", "transform".
 */

export type Locale = 'de' | 'en'

interface Localised {
  de: string
  en: string
}

interface LocalisedList {
  de: string[]
  en: string[]
}

export interface Industry {
  readonly slug: string
  readonly name: Localised
  /** One line under the heading. What this sector is, in our terms. */
  readonly summary: Localised
  readonly problem: Localised
  readonly reality: Localised
  readonly approach: LocalisedList
  readonly outcome: LocalisedList
  readonly next: Localised
  /** Roles we typically work with. Concrete, so the reader recognises themselves. */
  readonly whoWeWorkWith: LocalisedList
}

